import json
from pathlib import Path

root = Path('products/services/catalogue-gumroad')
source = root / 'file-evidence-inventory.json'
required = {'transform.py', 'verify.py', 'verify_example.py', 'fixtures/before-variants.csv', 'fixtures/before-images.csv', 'fixtures/after-shopify.csv'}
rows = []
for item in json.loads(source.read_text(encoding='utf-8'))['files']:
    if item['path'] in required:
        rows.append({'path': item['path'], 'sha256': item['sha256'], 'candidate_passage_count': len(item.get('rights_passages_for_manual_verification') or [])})
result = {'input': str(source), 'files': rows, 'missing_from_inventory': sorted(required - {row['path'] for row in rows}), 'interpretation': 'Passage counts are a screening result. Check original provenance or an applicable license before inferring permission. An empty result does not prove prohibition.'}
output = root / 'required-payload-rights-screen.json'
output.write_text(json.dumps(result, indent=2) + '\n', encoding='utf-8')
print(output.read_text(encoding='utf-8'))
